// Wire protocol with the game server (ADR-0015, slice 5 decision R). Hand-written types, held to the
// server by contract fixtures: ./fixtures/server/*.json are generated by the server's ContractFixturesTest
// and parsed strictly here, so a field added or renamed on either side fails a test.

export type Phase = 'PREPARATION' | 'RUNNING' | 'COMPLETE' | 'FAILED';

export type ClientAction =
  | { type: 'start_wave'; wave: number }
  | { type: 'apply_counter'; counter: string; option?: string }
  | { type: 'answer_postmortem'; option: string }
  | { type: 'run_action'; action: string; option?: string }
  | { type: 'remove_counter'; counter: string }
  | { type: 'configure_counter'; counter: string; value: number }
  | { type: 'pause' }
  | { type: 'resume' };

export interface Welcome {
  type: 'welcome';
  session: string;
  /** 64-bit, so a string: JavaScript numbers are exact only up to 2^53. */
  seed: string;
  tickHz: number;
  snapshotHz: number;
}

/** Fog-of-war view. Delta fields (insights, counters, codex, results, actions) are absent when unchanged. */
export interface Snapshot {
  type: 'snapshot';
  tick: number;
  credits: number;
  wave: number;
  phase: Phase;
  /** Error budget left in the running wave, 0..1. */
  shield: number;
  /** Budget spend speed vs. the pace that lasts the whole wave (1 = empty at the end); 0 outside a wave. */
  burnRate: number;
  /** Seconds until the shield breaks at the current failure rate; -1 when it is not burning. */
  shieldEmptyInS: number;
  /** Only the metrics the player's monitoring can measure, by exporter name. */
  metrics: Record<string, number>;
  signals: string[];
  insights?: string[];
  counters?: InstalledCounter[];
  /** Present while a postmortem is open or just answered; absent otherwise (not a delta field). */
  postmortem?: Postmortem;
  /** Opened codex entry ids, in the order earned; absent when unchanged (delta field). */
  codex?: string[];
  /** How each played wave ended, by wave number; absent when unchanged (delta field). */
  results?: WaveResult[];
  /** Present once the chapter is won (not a delta field). */
  chapter?: ChapterSummary;
  /** Crew points left in this shift. */
  crew: number;
  /** Latest run of each incident action used; absent when unchanged (delta field). */
  actions?: ActionRun[];
}

/** The latest run of an incident action. Windowed effects last until endTick; it may run again at readyTick. */
export interface ActionRun {
  id: string;
  option: string | null;
  startTick: number;
  endTick: number;
  readyTick: number;
}

export interface WaveResult {
  wave: number;
  survived: boolean;
  shield: number;
  /** Credits the wave paid: reward minus upkeep. */
  earned: number;
  /** null for a quiet wave or an unanswered postmortem. */
  postmortemRight: boolean | null;
}

export interface ChapterSummary {
  number: number;
  stars: number;
  averageShield: number;
  postmortemsRight: number;
  postmortems: number;
}

/** Root-cause question after a threat wave. Texts are i18n keys; `correct` is null until answered. */
export interface Postmortem {
  wave: number;
  questionKey: string;
  options: { id: string; key: string }[];
  chosen: string | null;
  correct: string | null;
}

/** A bought counter; it works from readyTick on and is being built before that. */
export interface InstalledCounter {
  id: string;
  option: string | null;
  readyTick: number;
  /** Tick its removal completes, or -1. */
  removedTick: number;
  /** The player's value for its setting, or null for the default. */
  setting: number | null;
}

/** GET /api/sessions/{id}/catalog: counters this session may see (insight-gated ones only once unlocked). */
export interface Catalog {
  language: string;
  crewPerShift: number;
  counters: CatalogItem[];
  actions: CatalogAction[];
}

/** An incident action card: costs crew, not credits, and cools down. */
export interface CatalogAction {
  id: string;
  name: string;
  realTech: string;
  detail: string;
  toil: number;
  cooldownS: number;
  options: { id: string; name: string; detail: string }[];
}

/** GET /api/sessions/{id}/codex: the articles this session has opened. */
export interface Codex {
  language: string;
  entries: CodexArticle[];
}

/** Plain text; a blank line separates paragraphs. */
export interface CodexArticle {
  id: string;
  title: string;
  body: string;
}

export interface CatalogItem {
  id: string;
  name: string;
  realTech: string;
  credits: number;
  upkeepPerWave: number;
  /** Crew points the purchase takes. */
  toil: number;
  applyTimeS: number;
  requiresCounters: string[];
  requiresInsight: string | null;
  grantsInsights: string[];
  tradeoff: string;
  options: CatalogOption[];
  /** False when undoing is impossible (a disk cannot shrink). */
  removable: boolean;
  /** The player-editable value that drives the effect, e.g. Nginx rate_rps. */
  setting: CatalogSetting | null;
}

export interface CatalogSetting {
  key: string;
  value: number;
  min: number;
  max: number;
}

export interface CatalogOption {
  id: string;
  name: string;
  /** Overrides the counter's build time when set. */
  applyTimeS: number | null;
  tradeoff: string;
}

export interface Rejected {
  type: 'rejected';
  action: ClientAction;
  reason: string;
}

export interface Paused {
  type: 'paused';
  paused: boolean;
}

export interface ErrorMessage {
  type: 'error';
  reason: string;
}

export type ServerMessage = Welcome | Snapshot | Rejected | Paused | ErrorMessage;

export class ProtocolError extends Error {}

const PHASES: readonly string[] = ['PREPARATION', 'RUNNING', 'COMPLETE', 'FAILED'];

type Obj = Record<string, unknown>;

function object(v: unknown, path: string): Obj {
  if (typeof v !== 'object' || v === null || Array.isArray(v)) throw new ProtocolError(`${path}: expected object`);
  return v as Obj;
}

/** Unknown keys are errors: a new server field must be added here deliberately. */
function keys(o: Obj, path: string, required: readonly string[], optional: readonly string[] = []): void {
  for (const k of required) if (!(k in o)) throw new ProtocolError(`${path}.${k}: missing`);
  for (const k of Object.keys(o)) {
    if (!required.includes(k) && !optional.includes(k)) throw new ProtocolError(`${path}.${k}: unknown field`);
  }
}

function num(v: unknown, path: string): number {
  if (typeof v !== 'number' || !Number.isFinite(v)) throw new ProtocolError(`${path}: expected number`);
  return v;
}

function str(v: unknown, path: string): string {
  if (typeof v !== 'string') throw new ProtocolError(`${path}: expected string`);
  return v;
}

function strings(v: unknown, path: string): string[] {
  if (!Array.isArray(v)) throw new ProtocolError(`${path}: expected array`);
  return v.map((s, i) => str(s, `${path}[${i}]`));
}

function metrics(v: unknown, path: string): Record<string, number> {
  const out: Record<string, number> = {};
  for (const [k, value] of Object.entries(object(v, path))) out[k] = num(value, `${path}.${k}`);
  return out;
}

function nullable<T>(v: unknown, path: string, parse: (v: unknown, path: string) => T): T | null {
  return v === null ? null : parse(v, path);
}

function list<T>(v: unknown, path: string, parse: (v: unknown, path: string) => T): T[] {
  if (!Array.isArray(v)) throw new ProtocolError(`${path}: expected array`);
  return v.map((item, i) => parse(item, `${path}[${i}]`));
}

function installed(v: unknown, path: string): InstalledCounter {
  const o = object(v, path);
  keys(o, path, ['id', 'option', 'readyTick', 'removedTick', 'setting']);
  return { id: str(o['id'], `${path}.id`), option: nullable(o['option'], `${path}.option`, str),
    readyTick: num(o['readyTick'], `${path}.readyTick`), removedTick: num(o['removedTick'], `${path}.removedTick`),
    setting: nullable(o['setting'], `${path}.setting`, num) };
}

function choice(v: unknown, path: string): { id: string; key: string } {
  const o = object(v, path);
  keys(o, path, ['id', 'key']);
  return { id: str(o['id'], `${path}.id`), key: str(o['key'], `${path}.key`) };
}

function postmortem(v: unknown, path: string): Postmortem {
  const o = object(v, path);
  keys(o, path, ['wave', 'questionKey', 'options', 'chosen', 'correct']);
  return {
    wave: num(o['wave'], `${path}.wave`),
    questionKey: str(o['questionKey'], `${path}.questionKey`),
    options: list(o['options'], `${path}.options`, choice),
    chosen: nullable(o['chosen'], `${path}.chosen`, str),
    correct: nullable(o['correct'], `${path}.correct`, str),
  };
}

function bool(v: unknown, path: string): boolean {
  if (typeof v !== 'boolean') throw new ProtocolError(`${path}: expected boolean`);
  return v;
}

function waveResult(v: unknown, path: string): WaveResult {
  const o = object(v, path);
  keys(o, path, ['wave', 'survived', 'shield', 'earned', 'postmortemRight']);
  return {
    wave: num(o['wave'], `${path}.wave`),
    survived: bool(o['survived'], `${path}.survived`),
    shield: num(o['shield'], `${path}.shield`),
    earned: num(o['earned'], `${path}.earned`),
    postmortemRight: nullable(o['postmortemRight'], `${path}.postmortemRight`, bool),
  };
}

function chapterSummary(v: unknown, path: string): ChapterSummary {
  const o = object(v, path);
  keys(o, path, ['number', 'stars', 'averageShield', 'postmortemsRight', 'postmortems']);
  return {
    number: num(o['number'], `${path}.number`),
    stars: num(o['stars'], `${path}.stars`),
    averageShield: num(o['averageShield'], `${path}.averageShield`),
    postmortemsRight: num(o['postmortemsRight'], `${path}.postmortemsRight`),
    postmortems: num(o['postmortems'], `${path}.postmortems`),
  };
}

function catalogOption(v: unknown, path: string): CatalogOption {
  const o = object(v, path);
  keys(o, path, ['id', 'name', 'applyTimeS', 'tradeoff']);
  return { id: str(o['id'], `${path}.id`), name: str(o['name'], `${path}.name`),
    applyTimeS: nullable(o['applyTimeS'], `${path}.applyTimeS`, num), tradeoff: str(o['tradeoff'], `${path}.tradeoff`) };
}

function catalogItem(v: unknown, path: string): CatalogItem {
  const o = object(v, path);
  keys(o, path, ['id', 'name', 'realTech', 'credits', 'upkeepPerWave', 'toil', 'applyTimeS', 'requiresCounters',
    'requiresInsight', 'grantsInsights', 'tradeoff', 'options', 'removable', 'setting']);
  return {
    id: str(o['id'], `${path}.id`),
    name: str(o['name'], `${path}.name`),
    realTech: str(o['realTech'], `${path}.realTech`),
    credits: num(o['credits'], `${path}.credits`),
    upkeepPerWave: num(o['upkeepPerWave'], `${path}.upkeepPerWave`),
    toil: num(o['toil'], `${path}.toil`),
    applyTimeS: num(o['applyTimeS'], `${path}.applyTimeS`),
    requiresCounters: strings(o['requiresCounters'], `${path}.requiresCounters`),
    requiresInsight: nullable(o['requiresInsight'], `${path}.requiresInsight`, str),
    grantsInsights: strings(o['grantsInsights'], `${path}.grantsInsights`),
    tradeoff: str(o['tradeoff'], `${path}.tradeoff`),
    options: list(o['options'], `${path}.options`, catalogOption),
    removable: bool(o['removable'], `${path}.removable`),
    setting: nullable(o['setting'], `${path}.setting`, catalogSetting),
  };
}

function catalogSetting(v: unknown, path: string): CatalogSetting {
  const o = object(v, path);
  keys(o, path, ['key', 'value', 'min', 'max']);
  return { key: str(o['key'], `${path}.key`), value: num(o['value'], `${path}.value`),
    min: num(o['min'], `${path}.min`), max: num(o['max'], `${path}.max`) };
}

function catalogAction(v: unknown, path: string): CatalogAction {
  const o = object(v, path);
  keys(o, path, ['id', 'name', 'realTech', 'detail', 'toil', 'cooldownS', 'options']);
  return {
    id: str(o['id'], `${path}.id`),
    name: str(o['name'], `${path}.name`),
    realTech: str(o['realTech'], `${path}.realTech`),
    detail: str(o['detail'], `${path}.detail`),
    toil: num(o['toil'], `${path}.toil`),
    cooldownS: num(o['cooldownS'], `${path}.cooldownS`),
    options: list(o['options'], `${path}.options`, (v2, p2) => {
      const option = object(v2, p2);
      keys(option, p2, ['id', 'name', 'detail']);
      return { id: str(option['id'], `${p2}.id`), name: str(option['name'], `${p2}.name`),
        detail: str(option['detail'], `${p2}.detail`) };
    }),
  };
}

function actionRun(v: unknown, path: string): ActionRun {
  const o = object(v, path);
  keys(o, path, ['id', 'option', 'startTick', 'endTick', 'readyTick']);
  return {
    id: str(o['id'], `${path}.id`),
    option: nullable(o['option'], `${path}.option`, str),
    startTick: num(o['startTick'], `${path}.startTick`),
    endTick: num(o['endTick'], `${path}.endTick`),
    readyTick: num(o['readyTick'], `${path}.readyTick`),
  };
}

function article(v: unknown, path: string): CodexArticle {
  const o = object(v, path);
  keys(o, path, ['id', 'title', 'body']);
  return { id: str(o['id'], `${path}.id`), title: str(o['title'], `${path}.title`), body: str(o['body'], `${path}.body`) };
}

export function parseCodex(v: unknown): Codex {
  const o = object(v, 'codex');
  keys(o, 'codex', ['language', 'entries']);
  return { language: str(o['language'], 'codex.language'), entries: list(o['entries'], 'codex.entries', article) };
}

export function parseCatalog(v: unknown): Catalog {
  const o = object(v, 'catalog');
  keys(o, 'catalog', ['language', 'crewPerShift', 'counters', 'actions']);
  return {
    language: str(o['language'], 'catalog.language'),
    crewPerShift: num(o['crewPerShift'], 'catalog.crewPerShift'),
    counters: list(o['counters'], 'catalog.counters', catalogItem),
    actions: list(o['actions'], 'catalog.actions', catalogAction),
  };
}

export function parseAction(v: unknown, path = 'action'): ClientAction {
  const o = object(v, path);
  switch (o['type']) {
    case 'start_wave':
      keys(o, path, ['type', 'wave']);
      return { type: 'start_wave', wave: num(o['wave'], `${path}.wave`) };
    case 'apply_counter': {
      keys(o, path, ['type', 'counter'], ['option']);
      const action: ClientAction = { type: 'apply_counter', counter: str(o['counter'], `${path}.counter`) };
      if (o['option'] !== undefined && o['option'] !== null) action.option = str(o['option'], `${path}.option`);
      return action;
    }
    case 'answer_postmortem':
      keys(o, path, ['type', 'option']);
      return { type: 'answer_postmortem', option: str(o['option'], `${path}.option`) };
    case 'remove_counter':
      keys(o, path, ['type', 'counter']);
      return { type: 'remove_counter', counter: str(o['counter'], `${path}.counter`) };
    case 'configure_counter':
      keys(o, path, ['type', 'counter', 'value']);
      return { type: 'configure_counter', counter: str(o['counter'], `${path}.counter`),
        value: num(o['value'], `${path}.value`) };
    case 'run_action': {
      keys(o, path, ['type', 'action'], ['option']);
      const action: ClientAction = { type: 'run_action', action: str(o['action'], `${path}.action`) };
      if (o['option'] !== undefined && o['option'] !== null) action.option = str(o['option'], `${path}.option`);
      return action;
    }
    case 'pause':
    case 'resume':
      keys(o, path, ['type']);
      return { type: o['type'] };
    default:
      throw new ProtocolError(`${path}.type: unknown action ${String(o['type'])}`);
  }
}

export function parseServerMessage(v: unknown): ServerMessage {
  const o = object(v, 'message');
  switch (o['type']) {
    case 'welcome':
      keys(o, 'welcome', ['type', 'session', 'seed', 'tickHz', 'snapshotHz']);
      return {
        type: 'welcome',
        session: str(o['session'], 'welcome.session'),
        seed: str(o['seed'], 'welcome.seed'),
        tickHz: num(o['tickHz'], 'welcome.tickHz'),
        snapshotHz: num(o['snapshotHz'], 'welcome.snapshotHz'),
      };
    case 'snapshot': {
      keys(o, 'snapshot', ['type', 'tick', 'credits', 'wave', 'phase', 'shield', 'burnRate', 'shieldEmptyInS',
        'metrics', 'signals', 'crew'], ['insights', 'counters', 'postmortem', 'codex', 'results', 'chapter', 'actions']);
      const phase = str(o['phase'], 'snapshot.phase');
      if (!PHASES.includes(phase)) throw new ProtocolError(`snapshot.phase: unknown ${phase}`);
      const s: Snapshot = {
        type: 'snapshot',
        tick: num(o['tick'], 'snapshot.tick'),
        credits: num(o['credits'], 'snapshot.credits'),
        wave: num(o['wave'], 'snapshot.wave'),
        phase: phase as Phase,
        shield: num(o['shield'], 'snapshot.shield'),
        burnRate: num(o['burnRate'], 'snapshot.burnRate'),
        shieldEmptyInS: num(o['shieldEmptyInS'], 'snapshot.shieldEmptyInS'),
        metrics: metrics(o['metrics'], 'snapshot.metrics'),
        signals: strings(o['signals'], 'snapshot.signals'),
        crew: num(o['crew'], 'snapshot.crew'),
      };
      if (o['insights'] !== undefined) s.insights = strings(o['insights'], 'snapshot.insights');
      if (o['counters'] !== undefined) s.counters = list(o['counters'], 'snapshot.counters', installed);
      if (o['postmortem'] !== undefined) s.postmortem = postmortem(o['postmortem'], 'snapshot.postmortem');
      if (o['codex'] !== undefined) s.codex = strings(o['codex'], 'snapshot.codex');
      if (o['results'] !== undefined) s.results = list(o['results'], 'snapshot.results', waveResult);
      if (o['chapter'] !== undefined) s.chapter = chapterSummary(o['chapter'], 'snapshot.chapter');
      if (o['actions'] !== undefined) s.actions = list(o['actions'], 'snapshot.actions', actionRun);
      return s;
    }
    case 'rejected':
      keys(o, 'rejected', ['type', 'action', 'reason']);
      return {
        type: 'rejected',
        action: parseAction(o['action'], 'rejected.action'),
        reason: str(o['reason'], 'rejected.reason'),
      };
    case 'paused':
      keys(o, 'paused', ['type', 'paused']);
      if (typeof o['paused'] !== 'boolean') throw new ProtocolError('paused.paused: expected boolean');
      return { type: 'paused', paused: o['paused'] };
    case 'error':
      keys(o, 'error', ['type', 'reason']);
      return { type: 'error', reason: str(o['reason'], 'error.reason') };
    default:
      throw new ProtocolError(`message.type: unknown ${String(o['type'])}`);
  }
}

/** JSON for a player action, field order as in ./fixtures/client. */
export function encodeAction(action: ClientAction): string {
  return JSON.stringify(action);
}
